  "explicacao": "Descontos e acréscimos não se somam — multiplicam-se os fatores. Desconto de 30% → ×0,70; acréscimo de 12% → ×1,12. Assim: R$ 250,00 × 0,70 × 1,12 = R$ 196,00.",
